What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    int count = 0;
    for (int i = 1; i <= 5; i++) {
        for (int j = i; j <= 5; j++) {
            if ((i + j) % 3 == 0) continue;
            count++;
        }
    }
    printf("%d", count);
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
#define SQ(x) x * x
int main() {
    printf("%d", SQ(2 + 3));
    return 0;
}
```

